repo.fixtures.py:
"""Fixture records."""


class Fixture:
    def __init__(self, club, goals):
        self.club = club
        self.goals = goals

    def __repr__(self):
        return "Fixture(%r, %r)" % (self.club, self.goals)


ROWS = [('city', 52), ('rovers', 30), ('town', 38), ('united', 53), ('united', 56)]


def load_fixtures():
    """Yield the stored fixtures one at a time."""
    for club, goals in ROWS:
        yield Fixture(club, goals)

repo.catalog.py:
"""Registry of fixtures by club."""

_ALL = []
_BY_KEY = None


def reset():
    """Forget every registered fixture."""
    global _BY_KEY
    del _ALL[:]
    _BY_KEY = None


def register(fixture):
    """Add one fixture to the registry."""
    _ALL.append(fixture)


def find(club):
    """Return the fixtures registered under this club."""
    global _BY_KEY
    if _BY_KEY is None:
        _BY_KEY = {}
        for x in _ALL:
            _BY_KEY.setdefault(x.club, []).append(x)
    return _BY_KEY.get(club, [])
